"""Block-scaled FP8 linear projection with a portable Torch fallback."""

import threading
from collections import OrderedDict
from dataclasses import dataclass

import torch
from torch.nn import functional as F


_BLOCK_SIZE = 128

# Dense packed projections use the existing native-FP8 microkernel through a
# one-expert schedule. These are storage shapes, rather than selector rows:
# the implementation has one geometry and falls back when its AOT shape is not
# shipped.
BLOCK_SCALED_LINEAR_FP8_SHAPES = (
    (6144, 5120, "block128"),
    (5120, 6144, "block128"),
    (14336, 5120, "block128"),
    (34816, 5120, "block128_interleaved8"),
    (16384, 5120, "block128"),
    (5120, 17408, "block128"),
)


def block_scaled_linear_fp8_config():
    from kestrel_kernels.cute_moe import CuteMoeConfig

    # On a 390x5120 by 6144x5120 packed projection on RTX PRO 6000,
    # native QMMA took 0.135 ms versus 0.261 ms for the portable warp
    # baseline, including activation quantization.
    # Tried M128/K128 across the four Qwen projection shapes at M128/390/820:
    # 0.536-1.359x M64/K64, winning only the widest shape at M390/820; keeping
    # M64/K64 until a shape-aware selector can retain the other projections.
    return CuteMoeConfig(
        block_m=64,
        block_n=128,
        block_k=64,
        num_warps=4,
        num_stages=2,
        dtype="fp8",
        kernel_type="qmma",
    )


@dataclass(frozen=True)
class _DenseRouting:
    sorted_token_ids: torch.Tensor
    block_offsets: torch.Tensor
    block_expert_ids: torch.Tensor
    topk_weights: torch.Tensor
    ready_event: torch.cuda.Event | None


_ROUTING_LOCK = threading.Lock()
_ROUTING_CACHE_BYTES = 32 * 1024 * 1024
_ROUTING: OrderedDict[tuple[int, int, int], _DenseRouting] = OrderedDict()


def _routing_bytes(route: _DenseRouting) -> int:
    return sum(
        tensor.numel() * tensor.element_size()
        for tensor in (
            route.sorted_token_ids,
            route.block_offsets,
            route.block_expert_ids,
            route.topk_weights,
        )
    )


def _dequantized_weight(
    weight: torch.Tensor,
    weight_scale_inv: torch.Tensor,
    *,
    quantized_rows: int,
    interleaved_parts: int,
    weight_tail: torch.Tensor | None,
    dtype: torch.dtype,
) -> torch.Tensor:
    rows = torch.arange(quantized_rows, device=weight.device)
    if interleaved_parts == 2:
        part = (rows // 8) % 2
        logical_row = (rows // 16) * 8 + rows % 8
    else:
        part = torch.zeros_like(rows)
        logical_row = rows
    scales = weight_scale_inv[part, logical_row // _BLOCK_SIZE]
    scales = scales.repeat_interleave(_BLOCK_SIZE, dim=1)[:, : weight.shape[1]]
    prefix = (
        weight[:quantized_rows].view(torch.float8_e4m3fn).float() * scales
    ).to(dtype)
    if weight_tail is None:
        return prefix
    return torch.cat((prefix, weight_tail.to(dtype)), dim=0)


def _validate(
    activation: torch.Tensor,
    weight: torch.Tensor,
    weight_scale_inv: torch.Tensor,
    *,
    quantized_rows: int,
    interleaved_parts: int,
    weight_tail: torch.Tensor | None,
    bias: torch.Tensor | None,
) -> None:
    if activation.ndim < 2:
        raise ValueError("block-scaled linear activation must be at least 2D")
    if activation.dtype not in (torch.bfloat16, torch.float16, torch.float32):
        raise ValueError("block-scaled linear activation must be BF16, FP16, or FP32")
    if weight.dtype != torch.uint8 or weight.ndim != 2:
        raise ValueError("block-scaled linear weight must be a 2D uint8 tensor")
    out_features, in_features = (int(dimension) for dimension in weight.shape)
    if int(activation.shape[-1]) != in_features:
        raise ValueError("activation and weight input dimensions do not match")
    if not 0 < quantized_rows <= out_features:
        raise ValueError("quantized_rows must be within the weight row extent")
    if interleaved_parts not in (1, 2):
        raise ValueError("interleaved_parts must be one or two")
    if interleaved_parts == 2 and (
        quantized_rows != out_features or out_features % 16
    ):
        raise ValueError("interleaved projections require complete eight-row pairs")
    rows_per_part = quantized_rows // interleaved_parts
    expected_scale_shape = (
        interleaved_parts,
        (rows_per_part + _BLOCK_SIZE - 1) // _BLOCK_SIZE,
        (in_features + _BLOCK_SIZE - 1) // _BLOCK_SIZE,
    )
    if (
        weight_scale_inv.dtype != torch.float32
        or tuple(weight_scale_inv.shape) != expected_scale_shape
    ):
        raise ValueError(
            "weight_scale_inv must be FP32 with shape "
            f"{expected_scale_shape}, got {tuple(weight_scale_inv.shape)}"
        )
    tail_rows = out_features - quantized_rows
    if tail_rows:
        if (
            weight_tail is None
            or weight_tail.dtype != torch.bfloat16
            or tuple(weight_tail.shape) != (tail_rows, in_features)
        ):
            raise ValueError(
                "weight_tail must be BF16 with the unquantized suffix shape"
            )
    elif weight_tail is not None:
        raise ValueError("weight_tail is only valid when quantized_rows is a prefix")
    if bias is not None and tuple(bias.shape) != (out_features,):
        raise ValueError("bias must have one element per output row")
    tensors = (weight, weight_scale_inv, weight_tail, bias)
    if any(
        tensor is not None and tensor.device != activation.device
        for tensor in tensors
    ):
        raise ValueError("block-scaled linear tensors must be on the same device")


def _routing(rows: int, block_m: int, device: torch.device) -> _DenseRouting:
    device_index = int(device.index or 0)
    key = (device_index, rows, block_m)
    with _ROUTING_LOCK:
        route = _ROUTING.get(key)
        if route is None:
            starts = list(range(0, rows, block_m))
            sorted_token_ids = torch.arange(rows, device=device, dtype=torch.int32)
            block_offsets = torch.tensor(
                [len(starts), *starts, rows], device=device, dtype=torch.int32
            )
            block_expert_ids = torch.zeros(
                len(starts), device=device, dtype=torch.int32
            )
            topk_weights = torch.ones(
                rows, device=device, dtype=torch.bfloat16
            )
            event = torch.cuda.Event(blocking=False, interprocess=False)
            event.record(torch.cuda.current_stream(device))
            route = _DenseRouting(
                sorted_token_ids=sorted_token_ids,
                block_offsets=block_offsets,
                block_expert_ids=block_expert_ids,
                topk_weights=topk_weights,
                ready_event=event,
            )
            _ROUTING[key] = route
            while (
                len(_ROUTING) > 1
                and sum(_routing_bytes(item) for item in _ROUTING.values())
                > _ROUTING_CACHE_BYTES
            ):
                _ROUTING.popitem(last=False)
        else:
            _ROUTING.move_to_end(key)
    assert route.ready_event is not None
    torch.cuda.current_stream(device).wait_event(route.ready_event)
    return route


def _native_eligible(
    activation: torch.Tensor,
    weight: torch.Tensor,
    weight_scale_inv: torch.Tensor,
    *,
    quantized_rows: int,
    interleaved_parts: int,
) -> bool:
    if (
        not activation.is_cuda
        or activation.dtype != torch.bfloat16
        or int(activation.shape[0]) == 0
        or not activation.is_contiguous()
        or not weight.is_contiguous()
        or not weight_scale_inv.is_contiguous()
        or int(weight.shape[1]) % _BLOCK_SIZE
        or quantized_rows % _BLOCK_SIZE
    ):
        return False
    if torch.cuda.get_device_capability(activation.device) != (12, 0):
        return False
    scale_layout = (
        "block128_interleaved8" if interleaved_parts == 2 else "block128"
    )
    shape = (quantized_rows, int(weight.shape[1]), scale_layout)
    if shape in BLOCK_SCALED_LINEAR_FP8_SHAPES:
        return True
    from kestrel_kernels.fallback import is_cute_jit_enabled

    return is_cute_jit_enabled()


def _native_prefix(
    activation_2d: torch.Tensor,
    weight: torch.Tensor,
    weight_scale_inv: torch.Tensor,
    *,
    quantized_rows: int,
    interleaved_parts: int,
) -> torch.Tensor:
    from kestrel_kernels.cute_moe.dispatch import invoke_cute_moe_down_fp8_compact

    config = block_scaled_linear_fp8_config()
    rows = int(activation_2d.shape[0])
    from kestrel_kernels.fp8_quant_cute import fp8_quant_cute

    activation_bits = torch.empty_like(activation_2d, dtype=torch.uint8)
    scale = torch.empty(
        rows, device=activation_2d.device, dtype=torch.float32)
    fp8_quant_cute(activation_bits, scale, activation_2d)
    route = _routing(rows, int(config.block_m), activation_2d.device)
    output = torch.empty(
        (rows, 1, quantized_rows),
        device=activation_2d.device,
        dtype=torch.bfloat16,
    )
    scale_layout = (
        "block128_interleaved8" if interleaved_parts == 2 else "block128"
    )
    kernel_scale = (
        weight_scale_inv.unsqueeze(0)
        if interleaved_parts == 2
        else weight_scale_inv
    )
    invoke_cute_moe_down_fp8_compact(
        activation_bits,
        scale,
        weight[:quantized_rows].unsqueeze(0),
        kernel_scale,
        output,
        topk_weights=route.topk_weights,
        sorted_token_ids=route.sorted_token_ids,
        block_offsets=route.block_offsets,
        block_expert_ids=route.block_expert_ids,
        config=config,
        weight_scale_layout=scale_layout,
    )
    stream = torch.cuda.current_stream(activation_2d.device)
    for tensor in (
        route.sorted_token_ids,
        route.block_offsets,
        route.block_expert_ids,
        route.topk_weights,
    ):
        tensor.record_stream(stream)
    return output[:, 0]


def block_scaled_linear(
    activation: torch.Tensor,
    weight: torch.Tensor,
    weight_scale_inv: torch.Tensor,
    *,
    quantized_rows: int | None = None,
    interleaved_parts: int = 1,
    weight_tail: torch.Tensor | None = None,
    bias: torch.Tensor | None = None,
) -> torch.Tensor:
    """Apply a block-scaled E4M3 projection without persistent dequantization."""

    quantized_rows = (
        int(weight.shape[0]) if quantized_rows is None else int(quantized_rows)
    )
    interleaved_parts = int(interleaved_parts)
    _validate(
        activation,
        weight,
        weight_scale_inv,
        quantized_rows=quantized_rows,
        interleaved_parts=interleaved_parts,
        weight_tail=weight_tail,
        bias=bias,
    )
    output_shape = (*activation.shape[:-1], int(weight.shape[0]))
    activation_2d = activation.reshape(-1, activation.shape[-1])
    if _native_eligible(
        activation_2d,
        weight,
        weight_scale_inv,
        quantized_rows=quantized_rows,
        interleaved_parts=interleaved_parts,
    ):
        prefix = _native_prefix(
            activation_2d,
            weight,
            weight_scale_inv,
            quantized_rows=quantized_rows,
            interleaved_parts=interleaved_parts,
        )
        if weight_tail is not None:
            prefix = torch.cat(
                (prefix, F.linear(activation_2d, weight_tail)),
                dim=1,
            )
        if bias is not None:
            prefix = prefix + bias.to(dtype=activation.dtype)
        return prefix.reshape(output_shape)

    dequantized = _dequantized_weight(
        weight,
        weight_scale_inv,
        quantized_rows=quantized_rows,
        interleaved_parts=interleaved_parts,
        weight_tail=weight_tail,
        dtype=activation.dtype,
    )
    normalized_bias = None if bias is None else bias.to(dtype=activation.dtype)
    return F.linear(activation, dequantized, normalized_bias)


__all__ = [
    "BLOCK_SCALED_LINEAR_FP8_SHAPES",
    "block_scaled_linear",
    "block_scaled_linear_fp8_config",
]
